previewCss:
.darma-loader-darma-b13-boom-barrier { --accent: var(--loader-color, #dc2626); --accent-2: var(--loader-secondary-color, #facc15); width: var(--loader-size, 124px); height: var(--loader-size, 124px); position: relative; }
.darma-loader-darma-b13-boom-barrier::before { content: ''; position: absolute; bottom: 6%; left: 5%; width: 8%; height: 44%; border-radius: 3px; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 30%, var(--accent-2))); }
.darma-loader-darma-b13-boom-barrier::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: 6%; background: repeating-linear-gradient(90deg, #94a3b8 0 9%, transparent 9% 18%); }
.darma-loader-darma-b13-boom-barrier .darma-loader-darma-b13-boom-barrier__arm { position: absolute; bottom: 36%; left: 11%; width: 52%; height: 7%; border-radius: 2px; transform-origin: left center; background: repeating-linear-gradient(90deg, var(--accent) 0 11%, #f8fafc 11% 22%); animation: darma-loader-darma-b13-boom-barrier-gate calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
@keyframes darma-loader-darma-b13-boom-barrier-gate { 0%, 12% { transform: rotate(-78deg); } 38%, 62% { transform: rotate(0deg); } 88%, 100% { transform: rotate(-78deg); } }

